-- Lost update: Two withdrawals read the balance, subtract in the application, and write it back.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 30, computed in the app
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 20, computed in the app
COMMIT;

-- Dirty read: T1 debits A, then rolls back. T2 copies A into a report row B in between.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 60, computed in the app
ROLLBACK;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :v WHERE id = 'B';  -- B = A, computed in the app
COMMIT;

