SELECT v FROM accounts WHERE id = 'B';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 20, computed in the app
UPDATE accounts SET v = :new_b WHERE id = 'B';  -- B = B + 20, computed in the app
COMMIT;

