UPDATE accounts SET v = :new_b WHERE id = 'B';  -- B = B - 10, computed in the app
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A + 10, computed in the app
