"""Strict two-phase locking with deadlock detection.

A teaching sketch of the algorithm the lab simulates, not a real lock manager.
Locks only grow while a transaction runs and are all released at commit.
"""


def execute(tx, stmt):
    mode = "S" if stmt.is_read else "X"
    request = LockRequest(tx, stmt.row, mode)
    if lock_table.compatible(request):
        lock_table.grant(request)  # held until commit: that is the "strict" part
        return run(tx, stmt)
    lock_table.enqueue(request)
    if wait_for_graph.has_cycle_through(tx):
        abort(tx, "deadlock detected")  # the victim; the client retries it
    return WAITING  # resumes when a holder releases


def run(tx, stmt):
    if stmt.is_read:
        return stmt.row.value
    stmt.row.write_uncommitted(tx, stmt.value)


def commit(tx):
    log.flush(tx)
    for lock in lock_table.held_by(tx):
        lock_table.release(lock)
    lock_table.wake_compatible_waiters()


def rollback(tx):
    undo_log.revert(tx)
    for lock in lock_table.held_by(tx):
        lock_table.release(lock)

"""Optimistic concurrency control: read, validate, write.

A teaching sketch of the algorithm the lab simulates. Nothing is locked while a
transaction runs; conflicts are found when it tries to commit.
"""


def begin(tx):
    tx.start = last_commit_ts


def read(tx, row):
    version = row.latest_committed
    tx.read_set[row] = version.commit_ts
    return tx.write_set.get(row, version.value)


def write(tx, row, value):
    tx.write_set[row] = value  # private: invisible to everyone else


def commit(tx):
    for row in tx.read_set:
        if row.latest_committed.commit_ts > tx.start:
            abort(tx, "validation failed")  # someone committed a change I read
    for row, value in tx.write_set.items():
        row.install(value, commit_ts=next_commit_ts())

"""Multi-version concurrency control: snapshot isolation, plus the SSI commit check.

A teaching sketch of the algorithm the lab simulates. Writers add versions instead
of overwriting, so readers never wait.
"""


def begin(tx):
    tx.snapshot = last_commit_ts


def read(tx, row):
    for version in reversed(row.versions):
        if version.writer is tx or version.commit_ts <= tx.snapshot:
            return version.value  # the newest version this snapshot can see


def write(tx, row, value):
    if row.lock not in (None, tx):
        wait_for(row.lock)  # MongoDB aborts here instead of waiting
    row.lock = tx
    if row.latest_committed.commit_ts > tx.snapshot:
        abort(tx, "could not serialize access")  # first-updater-wins
    row.versions.append(Version(value, writer=tx))


def commit(tx):
    if SERIALIZABLE and closes_dependency_cycle(tx):
        abort(tx, "serialization failure")  # SSI: rw-antidependency cycle
    tx.commit_ts = next_commit_ts()  # its versions become visible to new snapshots
    release_row_locks(tx)

"""One writer at a time, readers on a snapshot (SQLite in WAL mode).

A teaching sketch of the algorithm the lab simulates.
"""


def begin(tx):
    tx.snapshot = last_commit_ts


def read(tx, row):
    return row.version_at(tx.snapshot)


def write(tx, row, value):
    if writer_lock.holder not in (None, tx):
        wait_for(writer_lock.holder)  # busy_timeout
    if tx.snapshot < last_commit_ts:
        abort(tx, "SQLITE_BUSY_SNAPSHOT")  # my reads may be stale
    writer_lock.holder = tx
    wal.append(row, value)


def commit(tx):
    wal.commit(tx)
    writer_lock.holder = None
